export function parseParameters(newParameters, oldParameters) {
    // console.log(newParameters, oldParameters);
    if (newParameters === oldParameters) {
        return newParameters;
    }
    const parsedParameters = {};
    let output = '';

    for (const key in newParameters) {
        const isNewParam = oldParameters && !oldParameters[key];
        const isNotSet = newParameters[key] === undefined;
        const isSetButToDefault = oldParameters[key] === newParameters[key];
        if (isNewParam || isNotSet || isSetButToDefault) {
            continue;
        }
        const paramValue = newParameters[key];
        output += `-${key} ${paramValue} `;
        parsedParameters[key] = paramValue;
    }
    return { output, parsedParameters };
}
